{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection in AccountSearchController",
      "severity": "Medium",
      "file": "AccountSearchController.cls",
      "lines": "6",
      "explanation": "The method concatenates the user‑supplied searchKey directly into a dynamic SOQL string without escaping or binding, allowing an attacker to inject arbitrary SOQL clauses and potentially read or modify data beyond their permissions.",
      "remediation": "Use a bind variable or escape the input: String query = 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :searchKey LIMIT 50'; or String escaped = String.escapeSingleQuotes(searchKey); then build the query with the escaped value. Alternatively, use Database.queryWithBinds or static SOQL with a bind variable."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS Violation – Unrestricted Field Access",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "4-6",
      "explanation": "The class queries and updates a Contact record without enforcing field‑level security. It selects Name, Email, and Birthdate, which the permission set does not grant read access to, and performs a full record update, potentially modifying fields the user is not allowed to edit. This exposes sensitive data and allows unintended modifications.",
      "remediation": "Add WITH SECURITY_ENFORCED to the SOQL query or use Security.stripInaccessible to remove disallowed fields. Before performing the update, check that the user has edit permission on the fields being modified, or update only the Phone field (e.g., new Contact(Id=contactId, Phone=newPhone))."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Sharing rules not enforced on Aura-enabled method",
      "severity": "High",
      "file": "CaseHistoryController.cls",
      "lines": "1-12",
      "explanation": "The class is declared \"without sharing\" and the AuraEnabled method is reachable from Lightning components. The SOQL query returns all Case records (up to 200) without applying sharing rules, so users can see records they should not have access to. This exposes sensitive data to internal users beyond their record‑level permissions.",
      "remediation": "Declare the class or method with \"with sharing\" (or use WITH USER_MODE in the SOQL) and filter the query to only return records the user is allowed to see. Ensure the method is not exposed to guest users or other unauthenticated contexts."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive Data Access Permissions",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "userPermissions (ModifyAllData, ViewAllData)",
      "explanation": "The permission set grants ModifyAllData and ViewAllData, which allow users to read and modify all records in the org, far beyond the intended scope of viewing and closing cases. This violates the principle of least privilege and could enable privilege escalation if the permission set is assigned to users who should not have such broad access.",
      "remediation": "Remove the ModifyAllData and ViewAllData permissions from the permission set. Grant only the necessary object permissions (Case: Read, Edit) and the ApiEnabled permission if needed. If Apex execution requires higher privileges, consider using a dedicated integration user with a separate permission set that is tightly scoped."
    }
  ]
}
